<?php require 'config.php';auth();check();$id=filter_var($_POST['event_id']??null,FILTER_VALIDATE_INT);if(!$id)go('index.php');if(($_POST['action']??'')==='cancel'){$s=$db->prepare('DELETE FROM registrations WHERE event_id=? AND user_id=?');$s->execute([$id,$_SESSION['uid']]);go('my_events.php');}try{$db->beginTransaction();$s=$db->prepare('SELECT * FROM events WHERE id=? AND active=1 FOR UPDATE');$s->execute([$id]);$e=$s->fetch();if(!$e||strtotime($e['event_date'])<=time())throw new Exception('Unavailable');$s=$db->prepare('SELECT COUNT(*) FROM registrations WHERE event_id=?');$s->execute([$id]);if($s->fetchColumn()>=$e['capacity'])throw new Exception('Full');$s=$db->prepare('INSERT INTO registrations(user_id,event_id) VALUES(?,?)');$s->execute([$_SESSION['uid'],$id]);$db->commit();}catch(Throwable $ex){if($db->inTransaction())$db->rollBack();}go('my_events.php');